export type CheezCharacter = "calm" | "rushed" | "chaotic"

export type CheezTrigger =
  | "mount"
  | "in-view"
  | "hover"
  | "focus"
  | "manual"
  | "none"

export interface CheezTiming {
  duration: number
  delay?: number
  easing?: string
}

export interface CheezStrokeLayer {
  type: "stroke"
  path: string
  strokeWidth: number
  transform?: string
  opacity?: number
  timing: CheezTiming
}

export interface CheezFillLayer {
  type: "fill"
  path: string
  transform?: string
  opacity?: number
  reveal: {
    path: string
    strokeWidth: number
  }
  timing: CheezTiming
}

export type CheezLayer = CheezStrokeLayer | CheezFillLayer

export interface CheezPlacement {
  top: string
  left: string
  width: string
  height: string
}

export interface CheezDefinition {
  name: string
  viewBox: string
  placement: CheezPlacement
  layer: "behind" | "front"
  preserveAspectRatio?: "none" | "xMidYMid meet"
  layers: readonly CheezLayer[]
}

export type CheezDefinitionSet = Record<CheezCharacter, CheezDefinition>

export function validateCheezDefinition(definition: CheezDefinition) {
  if (definition.layers.length === 0) {
    return [`${definition.name} must contain at least one layer`]
  }

  const errors: string[] = []

  definition.layers.forEach((layer, index) => {
    if (!layer.path.trim()) {
      errors.push(`${definition.name} layer ${index} has an empty path`)
    }

    if (layer.timing.duration <= 0) {
      errors.push(`${definition.name} layer ${index} needs a positive duration`)
    }

    if (layer.type === "fill" && !layer.reveal.path.trim()) {
      errors.push(`${definition.name} layer ${index} has an empty reveal path`)
    }
  })

  return errors
}

const ANIMATED_LAYER_SELECTOR = "[data-cheez-animate]"
const DEFAULT_EASING = "cubic-bezier(.22,.72,.2,1)"

type PlayOptions = {
  durationScale?: number
  onComplete?: () => void
}

const inViewCallbacks = new WeakMap<Element, () => void>()
let inViewObserver: IntersectionObserver | undefined

function getAnimatedLayers(root: SVGSVGElement) {
  return Array.from(root.querySelectorAll<SVGElement>(ANIMATED_LAYER_SELECTOR))
}

function getLayerLength(layer: SVGElement) {
  const cachedLength = Number(layer.dataset.cheezLength)
  if (cachedLength > 0) return cachedLength

  const length = (layer as SVGGeometryElement).getTotalLength()
  layer.dataset.cheezLength = String(length)
  return length
}

function prepareLayer(layer: SVGElement, visible: boolean) {
  const length = getLayerLength(layer)
  layer.style.strokeDasharray = `${length} ${length}`
  layer.style.strokeDashoffset = visible ? "0" : String(length)
  layer.style.opacity = "1"
  return length
}

function shouldReduceMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function ensureInViewObserver() {
  if (inViewObserver) return inViewObserver

  inViewObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return
        inViewCallbacks.get(entry.target)?.()
      })
    },
    { threshold: 0.2 },
  )

  return inViewObserver
}

export function observeCheezMark(
  element: Element,
  callback: () => void,
  once = true,
) {
  const observer = ensureInViewObserver()
  const handleIntersection = () => {
    callback()

    if (once) {
      observer.unobserve(element)
      inViewCallbacks.delete(element)
    }
  }

  inViewCallbacks.set(element, handleIntersection)
  observer.observe(element)

  return () => {
    observer.unobserve(element)
    inViewCallbacks.delete(element)
  }
}

export function hideCheezMark(root: SVGSVGElement) {
  getAnimatedLayers(root).forEach((layer) => {
    prepareLayer(layer, false)
  })
}

export function finishCheezMark(root: SVGSVGElement) {
  getAnimatedLayers(root).forEach((layer) => {
    layer.getAnimations().forEach((animation) => animation.cancel())
    prepareLayer(layer, true)
  })
}

export function cancelCheezMark(root: SVGSVGElement) {
  getAnimatedLayers(root).forEach((layer) => {
    layer.getAnimations().forEach((animation) => animation.cancel())
  })
}

export function playCheezMark(
  root: SVGSVGElement,
  { durationScale = 1, onComplete }: PlayOptions = {},
) {
  const layers = getAnimatedLayers(root)

  cancelCheezMark(root)

  if (shouldReduceMotion()) {
    finishCheezMark(root)
    onComplete?.()
    return []
  }

  let completedLayers = 0

  return layers.map((layer) => {
    const length = prepareLayer(layer, false)

    const duration = Number(layer.dataset.duration) * durationScale
    const delay = Number(layer.dataset.delay ?? 0) * durationScale
    const animation = layer.animate(
      [
        { strokeDashoffset: String(length) },
        { strokeDashoffset: "0" },
      ],
      {
        duration,
        delay,
        easing: layer.dataset.easing ?? DEFAULT_EASING,
        fill: "both",
      },
    )

    animation.onfinish = () => {
      layer.style.strokeDashoffset = "0"
      animation.cancel()
      completedLayers += 1

      if (completedLayers === layers.length) onComplete?.()
    }

    return animation
  })
}

"use client"

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useRef,
  type ComponentPropsWithoutRef,
  type CSSProperties,
  type FocusEvent,
  type PointerEvent,
  type ReactNode,
} from "react"

import type {
  CheezDefinition,
  CheezFillLayer,
  CheezTrigger,
} from "./cheez-definition"
import {
  cancelCheezMark,
  finishCheezMark,
  hideCheezMark,
  observeCheezMark,
  playCheezMark,
} from "./cheez-motion"

export interface CheezMarkHandle {
  play: () => void
  replay: () => void
  cancel: () => void
  finish: () => void
}

export interface CheezMarkProps
  extends Omit<ComponentPropsWithoutRef<"span">, "children" | "color"> {
  children: ReactNode
  definition: CheezDefinition
  color?: string
  durationScale?: number
  once?: boolean
  thickness?: number
  trigger?: CheezTrigger
  onAnimationComplete?: () => void
}

interface AnimatedPathProps {
  duration: number
  delay?: number
  easing?: string
  initiallyVisible: boolean
}

const BASE_PATH_STYLE: CSSProperties = {
  transformOrigin: "center",
}

function getAnimatedPathProps({
  duration,
  delay = 0,
  easing,
  initiallyVisible,
}: AnimatedPathProps) {
  return {
    "data-cheez-animate": "",
    "data-duration": duration,
    "data-delay": delay,
    "data-easing": easing,
    style: {
      ...BASE_PATH_STYLE,
      opacity: initiallyVisible ? 1 : 0,
    },
  }
}

function FillLayer({
  layer,
  maskId,
  initiallyVisible,
}: {
  layer: CheezFillLayer
  maskId: string
  initiallyVisible: boolean
}) {
  const animatedPathProps = getAnimatedPathProps({
    ...layer.timing,
    initiallyVisible,
  })

  return (
    <>
      <defs>
        <mask
          id={maskId}
          maskUnits="userSpaceOnUse"
          x="-20%"
          y="-20%"
          width="140%"
          height="140%"
        >
          <path
            {...animatedPathProps}
            d={layer.reveal.path}
            transform={layer.transform}
            fill="none"
            stroke="white"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={layer.reveal.strokeWidth}
          />
        </mask>
      </defs>
      <path
        d={layer.path}
        fill="currentColor"
        mask={`url(#${maskId})`}
        opacity={layer.opacity ?? 1}
        transform={layer.transform}
      />
    </>
  )
}

export const CheezMark = forwardRef<CheezMarkHandle, CheezMarkProps>(
  function CheezMark(
    {
      children,
      className,
      color = "currentColor",
      definition,
      durationScale = 1,
      once = true,
      onAnimationComplete,
      onFocus,
      onPointerEnter,
      style,
      thickness = 1,
      trigger = "mount",
      ...props
    },
    forwardedRef,
  ) {
    const rootRef = useRef<HTMLSpanElement>(null)
    const svgRef = useRef<SVGSVGElement>(null)
    const reactId = useId().replaceAll(":", "")
    const initiallyVisible = trigger === "none"

    const play = useCallback(() => {
      if (!svgRef.current) return
      playCheezMark(svgRef.current, {
        durationScale,
        onComplete: onAnimationComplete,
      })
    }, [durationScale, onAnimationComplete])

    const replay = useCallback(() => {
      if (!svgRef.current) return
      hideCheezMark(svgRef.current)
      play()
    }, [play])

    const cancel = useCallback(() => {
      if (svgRef.current) cancelCheezMark(svgRef.current)
    }, [])

    const finish = useCallback(() => {
      if (svgRef.current) finishCheezMark(svgRef.current)
    }, [])

    useImperativeHandle(
      forwardedRef,
      () => ({ play, replay, cancel, finish }),
      [cancel, finish, play, replay],
    )

    useEffect(() => {
      const root = rootRef.current
      const svg = svgRef.current
      if (!root || !svg) return

      if (trigger === "none") {
        finishCheezMark(svg)
        return
      }

      if (trigger === "mount") {
        play()
        return () => cancelCheezMark(svg)
      }

      if (trigger === "in-view") {
        const stopObserving = observeCheezMark(root, replay, once)
        return () => {
          stopObserving()
          cancelCheezMark(svg)
        }
      }

      hideCheezMark(svg)
      return () => cancelCheezMark(svg)
    }, [definition.name, once, play, replay, trigger])

    const handlePointerEnter = (event: PointerEvent<HTMLSpanElement>) => {
      onPointerEnter?.(event)
      if (trigger === "hover") replay()
    }

    const handleFocus = (event: FocusEvent<HTMLSpanElement>) => {
      onFocus?.(event)
      if (trigger === "focus") replay()
    }

    const contentZIndex = definition.layer === "behind" ? 1 : 0
    const svgZIndex = definition.layer === "behind" ? 0 : 1

    return (
      <span
        {...props}
        ref={rootRef}
        className={className}
        onFocus={handleFocus}
        onPointerEnter={handlePointerEnter}
        style={{
          position: "relative",
          display: "inline-block",
          isolation: "isolate",
          ...style,
        }}
      >
        <span style={{ position: "relative", zIndex: contentZIndex }}>
          {children}
        </span>
        <svg
          ref={svgRef}
          aria-hidden="true"
          focusable="false"
          preserveAspectRatio={definition.preserveAspectRatio ?? "none"}
          viewBox={definition.viewBox}
          style={{
            position: "absolute",
            pointerEvents: "none",
            overflow: "visible",
            color,
            zIndex: svgZIndex,
            ...definition.placement,
          }}
        >
          {definition.layers.map((layer, index) => {
            if (layer.type === "fill") {
              return (
                <FillLayer
                  key={`${definition.name}-${index}`}
                  layer={layer}
                  maskId={`cheez-${reactId}-${index}`}
                  initiallyVisible={initiallyVisible}
                />
              )
            }

            return (
              <path
                {...getAnimatedPathProps({
                  ...layer.timing,
                  initiallyVisible,
                })}
                key={`${definition.name}-${index}`}
                d={layer.path}
                fill="none"
                opacity={layer.opacity ?? 1}
                stroke="currentColor"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={layer.strokeWidth * thickness}
                transform={layer.transform}
              />
            )
          })}
        </svg>
      </span>
    )
  },
)

"use client"

import { forwardRef } from "react"

import type {
  CheezCharacter,
  CheezDefinitionSet,
} from "./cheez-definition"
import {
  CheezMark,
  type CheezMarkHandle,
  type CheezMarkProps,
} from "./cheez-mark"

export interface CheezComponentProps
  extends Omit<CheezMarkProps, "definition"> {
  character?: CheezCharacter
}

export function createCheezMark(
  name: string,
  definitions: CheezDefinitionSet,
  defaultColor?: string,
) {
  const Component = forwardRef<CheezMarkHandle, CheezComponentProps>(
    function CheezComponent(
      { character = "calm", color = defaultColor, ...props },
      ref,
    ) {
      return (
        <CheezMark
          {...props}
          ref={ref}
          color={color}
          definition={definitions[character]}
        />
      )
    },
  )

  Component.displayName = name
  return Component
}
